:root {
  color-scheme: light;
  --ink: #302e46;
  --muted: #77758a;
  --paper: #fffdf8;
  --cream: #f4ead8;
  --lavender: #dcd5ff;
  --coral: #f28c78;
  --line: #e8e1d5;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
}
* { box-sizing: border-box; }
[hidden] { display: none !important; }
body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 36px 16px;
  display: grid;
  place-items: start center;
  color: var(--ink);
  background-color: var(--cream);
  background-image: radial-gradient(#d5c7ae 1px, transparent 1px);
  background-size: 18px 18px;
}
button, input, textarea { font: inherit; }
.board {
  width: min(100%, 620px);
  padding: 30px;
  background: var(--paper);
  border: 2px solid var(--ink);
  box-shadow: 7px 7px 0 var(--ink);
}
.topbar { display: flex; align-items: center; gap: 14px; padding-bottom: 22px; border-bottom: 2px dashed var(--line); }
.pixel-mark { width: 46px; height: 46px; display: grid; place-items: center; color: var(--ink); background: var(--lavender); border: 2px solid var(--ink); box-shadow: 3px 3px 0 var(--ink); font-size: 25px; }
.eyebrow { margin: 0 0 2px; color: var(--muted); font-size: 12px; font-weight: 800; letter-spacing: .12em; }
h1, h2, p { margin-top: 0; }
h1 { margin-bottom: 0; font-size: 27px; line-height: 1.2; }
.note-total { margin-left: auto; padding: 7px 10px; color: var(--ink); background: var(--cream); border: 1px solid var(--ink); font-size: 14px; font-weight: 700; white-space: nowrap; }
.note-form { display: grid; gap: 9px; padding: 22px 0 24px; }
label { font-size: 15px; font-weight: 750; }
.label-hint, .heading-hint { color: var(--muted); font-size: 13px; font-weight: 500; }
input, textarea { width: 100%; padding: 11px 12px; color: var(--ink); background: #fff; border: 1.5px solid #b9b4c4; border-radius: 0; outline: none; }
textarea { min-height: 76px; resize: vertical; }
input::placeholder, textarea::placeholder { color: #9692a0; }
input:focus, textarea:focus { border-color: var(--ink); box-shadow: 0 0 0 3px var(--lavender); }
.add-button, .clear-button, .tag-chip { cursor: pointer; }
.add-button { justify-self: start; margin-top: 4px; padding: 10px 15px; color: var(--paper); background: var(--ink); border: 2px solid var(--ink); box-shadow: 3px 3px 0 var(--coral); font-weight: 750; }
.add-button span { margin-right: 4px; font-size: 20px; line-height: 0; vertical-align: -1px; }
button:hover { filter: brightness(1.08); transform: translateY(-1px); }
button:active { transform: translate(2px, 2px); box-shadow: none; }
button:focus-visible { outline: 3px solid var(--coral); outline-offset: 3px; }
.tag-section { padding: 17px 0 22px; border-top: 2px dashed var(--line); }
.section-heading { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 12px; }
h2 { margin-bottom: 0; font-size: 18px; }
.tag-list { display: flex; flex-wrap: wrap; gap: 8px; }
.tag-chip { display: inline-flex; align-items: center; gap: 7px; padding: 6px 9px; color: var(--ink); background: var(--lavender); border: 1px solid var(--ink); font-size: 14px; }
.tag-chip[aria-pressed="true"] { color: var(--paper); background: var(--ink); }
.tag-count { font-size: 12px; font-weight: 800; opacity: .75; }
.tag-empty { margin: 0; color: var(--muted); font-size: 14px; }
.notes-section { padding-top: 17px; border-top: 2px dashed var(--line); }
.notes-heading { align-items: flex-start; }
.active-filter { display: flex; align-items: center; gap: 8px; color: var(--muted); font-size: 14px; }
.active-filter strong { color: var(--ink); }
.clear-button { padding: 4px 7px; color: var(--ink); background: transparent; border: 1px solid var(--ink); font-size: 13px; }
.notes-list { display: grid; gap: 10px; }
.note-card { padding: 14px; background: #fff; border: 1px solid var(--line); border-left: 4px solid var(--coral); box-shadow: 2px 2px 0 #eee8de; }
.note-copy { margin: 0 0 11px; white-space: pre-wrap; overflow-wrap: anywhere; line-height: 1.55; }
.note-tags { display: flex; flex-wrap: wrap; gap: 6px; }
.note-tag { padding: 3px 7px; color: var(--ink); background: var(--cream); font-size: 13px; }
.empty-state { margin: 0; padding: 23px 12px; color: var(--muted); background: #faf7f0; text-align: center; line-height: 1.5; }
footer { margin-top: 24px; color: var(--muted); text-align: center; font-size: 13px; }
footer span { margin-left: 4px; color: var(--coral); }
@media (max-width: 480px) {
  body { padding: 20px 14px; }
  .board { padding: 22px 18px; box-shadow: 5px 5px 0 var(--ink); }
  h1 { font-size: 24px; }
  .topbar { gap: 11px; }
  .note-total { padding: 6px 7px; font-size: 13px; }
  .section-heading { align-items: flex-start; }
}

const form = document.querySelector('#note-form');
const textInput = document.querySelector('#note-text');
const tagsInput = document.querySelector('#note-tags');
const notesList = document.querySelector('#notes-list');
const tagList = document.querySelector('#tag-list');
const emptyState = document.querySelector('#empty-state');
const noteTotal = document.querySelector('#note-total');
const activeFilter = document.querySelector('#active-filter');
const filterName = document.querySelector('#filter-name');
const clearFilter = document.querySelector('#clear-filter');

let notes = [];
let selectedTag = null;

function parseTags(value) {
  const seen = new Set();
  return value.split(',').map(tag => tag.trim()).filter(tag => {
    const key = tag.toLocaleLowerCase();
    if (!tag || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function render() {
  const counts = new Map();
  notes.forEach(note => note.tags.forEach(tag => {
    const key = tag.toLocaleLowerCase();
    const item = counts.get(key) || { label: tag, count: 0 };
    item.count += 1;
    counts.set(key, item);
  }));

  tagList.replaceChildren();
  if (!counts.size) {
    const message = document.createElement('p');
    message.className = 'tag-empty';
    message.textContent = 'Your tags will show up here.';
    tagList.append(message);
  }
  [...counts.entries()].sort((a, b) => a[1].label.localeCompare(b[1].label)).forEach(([key, item]) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'tag-chip';
    button.setAttribute('aria-pressed', String(selectedTag === key));
    button.setAttribute('aria-label', `Filter by ${item.label}, ${item.count} ${item.count === 1 ? 'note' : 'notes'}`);
    const label = document.createElement('span');
    label.textContent = `#${item.label}`;
    const count = document.createElement('span');
    count.className = 'tag-count';
    count.textContent = item.count;
    button.append(label, count);
    button.addEventListener('click', () => {
      selectedTag = selectedTag === key ? null : key;
      render();
    });
    tagList.append(button);
  });

  const visibleNotes = notes.filter(note => !selectedTag || note.tags.some(tag => tag.toLocaleLowerCase() === selectedTag));
  notesList.replaceChildren();
  visibleNotes.forEach(note => {
    const card = document.createElement('article');
    card.className = 'note-card';
    const copy = document.createElement('p');
    copy.className = 'note-copy';
    copy.textContent = note.text;
    const tagRow = document.createElement('div');
    tagRow.className = 'note-tags';
    note.tags.forEach(tag => {
      const chip = document.createElement('span');
      chip.className = 'note-tag';
      chip.textContent = `#${tag}`;
      tagRow.append(chip);
    });
    card.append(copy);
    if (note.tags.length) card.append(tagRow);
    notesList.append(card);
  });

  noteTotal.textContent = `${notes.length} ${notes.length === 1 ? 'note' : 'notes'}`;
  activeFilter.hidden = !selectedTag;
  if (selectedTag) {
    const selected = counts.get(selectedTag);
    filterName.textContent = `#${selected ? selected.label : selectedTag}`;
  }
  emptyState.hidden = visibleNotes.length > 0;
  emptyState.textContent = selectedTag && !visibleNotes.length
    ? `No notes tagged “${filterName.textContent}” yet.`
    : 'Nothing pinned here yet. Add a note to get started.';
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const text = textInput.value.trim();
  if (!text) {
    textInput.focus();
    return;
  }
  notes.unshift({ text, tags: parseTags(tagsInput.value) });
  form.reset();
  textInput.focus();
  render();
});

clearFilter.addEventListener('click', () => {
  selectedTag = null;
  render();
});

render();
